import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonSet from '@jetbrains/ring-ui-built/components/button-set/button-set'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import classNames from 'classnames'
import {memo} from 'react'

import type {PipelineId, ProjectId} from '../../../../../types'
import type {VcsProvider} from '../../services/pipelinesApi.types'
import {isStatusPublishingFeatureEnabled} from '../../utils/featureToggles'
import BranchSpecificationSelect from '../BranchSpecificationSelect/BranchSpecificationSelect'
import DefaultBranchSelect from '../DefaultBranchSelect/DefaultBranchSelect'
import ExistingVcsRootSelect from '../ExistingVcsRootSelect/ExistingVcsRootSelect'
import RepositorySelect from '../RepositorySelect/RepositorySelect'
import SlideInOutAnimation from '../SlideInOutAnimation/SlideInOutAnimation'
import VcsAnyRepositoryAuthenticationForm from '../VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm'
import VcsLoginLink from '../VcsLoginLink/VcsLoginLink'
import VcsProviderSelect from '../VcsProviderSelect/VcsProviderSelect'

import AdvancedIntegrationSection from './AdvancedIntegrationSection/AdvancedIntegrationSection'
import ExistingVcsRootForm from './ExistingVcsRootForm/ExistingVcsRootForm'
import PipelineNameInput from './PipelineNameInput/PipelineNameInput'
import RepositoryEditUrl from './RepositoryEditUrl/RepositoryEditUrl'
import RepositoryNameInput from './RepositoryNameInput/RepositoryNameInput'
import usePipelineForm from './usePipelineForm'

import styles from './PipelineForm.module.css'

import Alert from 'src/components/common/Alert/Alert'

type Props = {
  vcsProviders: VcsProvider[]
  authorizedProvider: VcsProvider
  onVcsLogin?: () => void
  cancelButton?: React.ReactNode
  pipelineId?: PipelineId
  projectId?: ProjectId
}
function PipelineForm({
  vcsProviders,
  authorizedProvider,
  onVcsLogin,
  cancelButton,
  pipelineId,
  projectId,
}: Props) {
  const {
    vcsRootId,
    vcsName,
    pipelineName,
    isRepoSelected,
    isFormValid,
    isShowLoginAlert,
    defaultBranch,
    branchSpecification,
    trackPullRequests,
    isNotAuthorized,
    hasError,
    selectedRepo,
    selectedProvider,
    isLoading,
    onVcsLoginWithErrorReset,
    onError,
    isVcsProviderTypeAny,
    isExistingVcsRootProvider,
    isShowVcsAnyRepositoryAuthenticationForm,
    isAnyVcsProviderVerified,
    vcsHttpsRepositoryAuthType,
    vcsProtocolRepositoryAuthType,
    vcsProtocolRepositoryAuthenticationFormChangeHandler,
    vcsHttpsRepositoryAuthenticationFormChangeAuthTypeHandler,
    vcsProviderVerifiedLabelButtonClickHandler,
    vcsAnyRepositoryAuthenticationFormSubmitHandler,
    repositoryNameInputChangeHandler,
    repositoryNameSelectChangeHandler,
    setPipelineName,
    setDefaultBranch,
    selectVcsProviderSelectChangeHandler,
    setPipelineNameError,
    setBranchSpecification,
    setTrackPullRequests,
    selectVcsRootHandler,
    formSubmitHandler,
    clickCancelButtonHandler,
  } = usePipelineForm(vcsProviders, authorizedProvider, onVcsLogin, pipelineId, projectId)

  const formBottomSection = (
    <>
      {isStatusPublishingFeatureEnabled && selectedProvider.connectionId != null && (
        <div className={classNames(styles.formInner, styles.extraPadding)}>
          <label>{'Advanced integration'}</label>
          <AdvancedIntegrationSection />
        </div>
      )}
      {!pipelineId && (
        <div className={classNames(styles.formInner, styles.extraPadding)}>
          <label className={styles.pipelineName}>{'Pipeline name'}</label>
          <PipelineNameInput
            name={pipelineName}
            onNameChange={setPipelineName}
            onValidate={setPipelineNameError}
          />
        </div>
      )}
    </>
  )

  if (projectId == null) {
    return null
  }

  return (
    <form autoComplete="off" onSubmit={formSubmitHandler}>
      <div className={classNames(styles.formInner, styles.repoBlock)}>
        <VcsProviderSelect
          projectId={projectId}
          vcsProviders={vcsProviders}
          selected={selectedProvider}
          onSelectProvider={selectVcsProviderSelectChangeHandler}
          onLogin={onVcsLoginWithErrorReset}
        />
        {isVcsProviderTypeAny ? (
          <RepositoryNameInput
            value={selectedRepo?.url}
            disabled={isAnyVcsProviderVerified}
            onChange={repositoryNameInputChangeHandler}
          />
        ) : isExistingVcsRootProvider ? (
          <ExistingVcsRootSelect projectId={projectId} onVcsRootSelect={selectVcsRootHandler} />
        ) : (
          <RepositorySelect
            projectId={projectId}
            vcsProvider={selectedProvider}
            selected={selectedRepo}
            onSelectRepository={repositoryNameSelectChangeHandler}
            disabled={isNotAuthorized || hasError}
            onError={onError}
            autoFocus
          />
        )}
        {isShowLoginAlert && selectedProvider.connectionId && (
          <Alert className={styles.loginAlert} contentClassName={styles.loginAlertContent}>
            {`To show available repositories TeamCity requires access to your ${selectedProvider.displayName} account.`}
            <VcsLoginLink
              className={styles.loginLink}
              connectionId={selectedProvider.connectionId}
              onLogin={onVcsLoginWithErrorReset}
              projectId={projectId}
            />
          </Alert>
        )}
      </div>
      {isShowVcsAnyRepositoryAuthenticationForm && (
        <VcsAnyRepositoryAuthenticationForm
          key={`${vcsProtocolRepositoryAuthType}-${projectId}`}
          projectId={projectId}
          url={selectedRepo?.url}
          password={selectedProvider?.password}
          username={selectedProvider?.username}
          vcsProtocol={vcsProtocolRepositoryAuthType}
          onChangeVcsProtocol={vcsProtocolRepositoryAuthenticationFormChangeHandler}
          httpsAuthType={vcsHttpsRepositoryAuthType}
          onChangeHttpsAuthType={vcsHttpsRepositoryAuthenticationFormChangeAuthTypeHandler}
          onSumbit={vcsAnyRepositoryAuthenticationFormSubmitHandler}
          cancelButton={cancelButton}
        />
      )}
      {isAnyVcsProviderVerified && (
        <RepositoryEditUrl
          vcsProtocol={vcsProtocolRepositoryAuthType}
          className={styles.repositoryEditUrl}
          onClick={vcsProviderVerifiedLabelButtonClickHandler}
        />
      )}
      {isExistingVcsRootProvider ? (
        <ExistingVcsRootForm vcsRootId={vcsRootId} vcsName={vcsName}>
          {formBottomSection}
        </ExistingVcsRootForm>
      ) : (
        <SlideInOutAnimation show={isRepoSelected} mountOnEnter unmountOnExit>
          <div className={styles.formInner}>
            <label>{'Default branch'}</label>
            <DefaultBranchSelect
              projectId={projectId}
              vcsProtocol={vcsProtocolRepositoryAuthType}
              vcsProvider={selectedProvider}
              selected={defaultBranch}
              onSelectBranch={setDefaultBranch}
              repoUrl={selectedRepo?.url}
              repoDefaultBranch={selectedRepo?.defaultBranch}
            />
            <label className={styles.branches}>{'Branches to monitor'}</label>
            <BranchSpecificationSelect
              isPullRequestsSupported={selectedProvider?.pullRequestTriggersSupported}
              specification={branchSpecification}
              defaultBranch={defaultBranch}
              isPullRequestsEnabled={trackPullRequests}
              onSelectSpecification={setBranchSpecification}
              onTogglePullRequests={setTrackPullRequests}
            />
          </div>
          {formBottomSection}
        </SlideInOutAnimation>
      )}
      {!isShowVcsAnyRepositoryAuthenticationForm && (
        <ButtonSet className={styles.actions}>
          <Button
            type={'submit'}
            disabled={!isFormValid}
            loader={isLoading}
            primary
            height={ControlsHeight.M}
          >
            {pipelineId ? 'Add' : 'Create'}
          </Button>
          {cancelButton ? (
            cancelButton
          ) : (
            <Button onClick={clickCancelButtonHandler} height={ControlsHeight.M}>
              {'Cancel'}
            </Button>
          )}
        </ButtonSet>
      )}
    </form>
  )
}

export default memo(PipelineForm)
