import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import type {FetchBaseQueryError} from '@reduxjs/toolkit/query'
import {useCallback, useEffect, useState} from 'react'
import {useLocation, useNavigate} from 'react-router'

import {getPipelineHref} from '../../../../../routes'
import type {PipelineId} from '../../../../../types'
import {getExtractErrorMessage} from '../../EditPipelinePage/EditPipelinePage.utils'
import {pipelinesApi} from '../../services/pipelinesApi'
import type {NewVcsRootDto, Pipeline} from '../../services/pipelinesApi.types'
import {instanceOf} from '../../types'

function processError(error: unknown) {
  let errorText = (error instanceof Error && error.message) || 'Failed to update the pipeline'
  if (instanceOf<FetchBaseQueryError>(error, 'status')) {
    errorText = getExtractErrorMessage(error)
  }
  alertService.error(errorText)
}
type UpdatePipelineArg = {
  pipelineId?: PipelineId
  repositoryUrl?: string
  branch?: string
  branchSpecification?: string
  isPrivate?: boolean
  connectionId?: string
  password?: string
  username?: string
  sshKey?: {
    name: string
    passphrase?: string
  }
  externalVcsRootId?: string
  isExternal?: boolean
}
export function useUpdatePipeline(): {
  updatePipeline: (arg: UpdatePipelineArg) => void
  pipelineUpdating: boolean
} {
  const location = useLocation()
  const [pipelineUpdating, setPipelineUpdating] = useState<boolean>(false)
  const [update, {error}] = pipelinesApi.endpoints.updatePipeline.useMutation()
  const [getPipeline] = pipelinesApi.endpoints.getPipelineById.useLazyQuerySubscription()

  useEffect(() => {
    if (error) {
      processError(error)
    }
  }, [error])
  const navigate = useNavigate()
  const updatePipeline = useCallback(
    async ({
      pipelineId,
      repositoryUrl,
      branch,
      branchSpecification,
      isPrivate,
      connectionId,
      username,
      password,
      sshKey,
      externalVcsRootId,
    }: UpdatePipelineArg) => {
      if (pipelineId == null) {
        return
      }
      setPipelineUpdating(true)
      try {
        const {data: pipeline} = await getPipeline(pipelineId)
        const pipelineResult = await update({
          id: pipelineId,
          body: {
            ...(pipeline as Pipeline),
            vcsRoot: {
              externalVcsRootId,
              url: repositoryUrl,
              branch,
              branchSpecification,
              vcsName: externalVcsRootId == null ? 'jetbrains.git' : undefined,
              isPrivate,
              connectionId,
              username,
              password,
              sshKey,
            } as NewVcsRootDto,
          },
        })
        if ('data' in pipelineResult && pipelineResult.data != null) {
          navigate(location.state?.redirectTo ?? `${getPipelineHref(pipelineResult.data.id)}`)
        }
      } catch (e) {
        processError(e)
      } finally {
        setPipelineUpdating(false)
      }
    },
    [getPipeline, update, navigate, location.state?.redirectTo],
  )

  return {pipelineUpdating, updatePipeline}
}
