import {HTTPCodesEnum} from '@jetbrains/teamcity-ui/dist/services'
import type {SerializedError} from '@reduxjs/toolkit'
import type {FetchBaseQueryError} from '@reduxjs/toolkit/query'
import {skipToken} from '@reduxjs/toolkit/query'
import type {ChangeEvent, FormEvent} from 'react'
import {useRef, useEffect, useCallback, useMemo, useState} from 'react'
import {useSearchParams} from 'react-router'

import type {PipelineId, ProjectId} from '../../../../../types'
import {pipelinesApi} from '../../services/pipelinesApi'
import type {VcsProvider} from '../../services/pipelinesApi.types'
import {VcsProviderType} from '../../services/pipelinesApi.types'
import {isProjectsAndBuildTypesEnabled} from '../../utils/featureToggles'
import {allBranchesSpecification} from '../BranchSpecificationSelect/BranchSpecificationSelect.consts'
import {branchNameDefault} from '../DefaultBranchSelect/DefaultBranchSelect.consts'
import type {SelectedRepository} from '../RepositorySelect/RepositorySelect.types'
import {
  HttpsRepositoryAuthType,
  ProtocolVcsRepository,
} from '../VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm.consts'

import {generatePipelineName, getGuessedGitProtocol} from './PipelineForm.utils'
import useCreatePipeline from './useCreatePipeline'
import {useUpdatePipeline} from './useUpdatePipeline'

function usePipelineForm(
  vcsProviders: VcsProvider[],
  authorizedProvider: VcsProvider,
  onVcsLogin?: () => void,
  pipelineId?: PipelineId,
  projectId?: ProjectId,
) {
  const isProtocolManuallyChangedRef = useRef<boolean>(false)
  const {createPipeline, pipelineCreating} = useCreatePipeline()
  const {updatePipeline, pipelineUpdating} = useUpdatePipeline()
  const [selectedProvider, setSelectedProvider] = useState<VcsProvider>(authorizedProvider)
  const [vcsRootId, setVcsRootId] = useState<string | null>(null)
  const [vcsName, setVcsName] = useState('')
  const [selectedRepo, setSelectedRepo] = useState<SelectedRepository | null>(null)
  const [hasError, setHasError] = useState<boolean>(false)
  const [defaultBranch, setDefaultBranch] = useState<string | null>(null)
  const [branchSpecification, setBranchSpecification] = useState(allBranchesSpecification)
  const [trackPullRequests, setTrackPullRequests] = useState(true)
  const [isAnyVcsProviderVerified, setIsAnyVcsProviderVerified] = useState<boolean>(false)

  const {data: pipelines} = pipelinesApi.endpoints.getAllPipelines.useQuery(
    pipelineId ? skipToken : {parentProjectId: projectId},
  )
  const pipelineNames = useMemo(() => pipelines?.map(pipeline => pipeline.name) ?? [], [pipelines])
  const onError = useCallback((error: FetchBaseQueryError | SerializedError | null) => {
    if (
      error != null &&
      'status' in error &&
      ((error.status === HTTPCodesEnum.NOT_FOUND &&
        'data' in error &&
        typeof error.data === 'string' &&
        (error.data.includes('No user tokens found') || error.data.includes('Bad credentials'))) ||
        error.status === HTTPCodesEnum.INTERNAL_SERVER_ERROR)
    ) {
      setHasError(true)
    }
  }, [])

  const [pipelineName, setPipelineName] = useState('')
  const [hasPipelineNameError, setPipelineNameError] = useState(false)

  const isNotAuthorized = selectedProvider.username == null
  const onVcsLoginWithErrorReset = useCallback(() => {
    setHasError(false)
    onVcsLogin?.()
  }, [onVcsLogin])
  const isExistingVcsRootProvider = selectedProvider.type === VcsProviderType.EXISTING_VCS_ROOT
  const isVcsProviderTypeAny = selectedProvider.type === VcsProviderType.ANY
  const isShowVcsAnyRepositoryAuthenticationForm = isVcsProviderTypeAny && !isAnyVcsProviderVerified
  const isShowLoginAlert = (!isVcsProviderTypeAny && isNotAuthorized) || hasError
  const isRepoSelected =
    (!!selectedRepo?.url && !isVcsProviderTypeAny) ||
    (isVcsProviderTypeAny && isAnyVcsProviderVerified)

  const isVcsRootSelected = vcsRootId != null
  const [vcsHttpsRepositoryAuthType, setVcsHttpsRepositoryAuthType] =
    useState<HttpsRepositoryAuthType>(HttpsRepositoryAuthType.TOKEN)
  const [vcsProtocolRepositoryAuthType, setVcsProtocolRepositoryAuthType] =
    useState<ProtocolVcsRepository>(ProtocolVcsRepository.SSH)
  const vcsHttpsRepositoryAuthenticationFormChangeAuthTypeHandler = (
    value: HttpsRepositoryAuthType,
  ) => setVcsHttpsRepositoryAuthType(value)
  const vcsProtocolRepositoryAuthenticationFormChangeHandler = (value: ProtocolVcsRepository) => {
    setVcsProtocolRepositoryAuthType(value)

    isProtocolManuallyChangedRef.current = true

    setSelectedProvider(state => ({
      ...state,
      username: undefined,
      password: undefined,
    }))
  }

  const isParentProjectSelected =
    !isProjectsAndBuildTypesEnabled() || (projectId != null && projectId !== '')
  const isRepoValid = isRepoSelected || isVcsRootSelected
  const isPipelineNameValid = pipelineName.length > 0 && !hasPipelineNameError
  const isFormValid = pipelineId
    ? isRepoValid
    : isRepoValid && isPipelineNameValid && isParentProjectSelected

  const getPipelineName = (url: string) => {
    const repositoryPathName = url.split('/').pop() ?? ''

    return repositoryPathName.replace(/\.git$/, '')
  }
  const generatePipelineNameHandler = (url: string) => {
    try {
      const repositoryName = getPipelineName(url)
      const generatedName = generatePipelineName(repositoryName, pipelineNames)

      setPipelineName(generatedName)
    } catch {
      // do nothing
    }
  }
  const repositoryNameSelectChangeHandler = (value: SelectedRepository | null) => {
    setSelectedRepo(value)
    generatePipelineNameHandler(value?.url ?? '')
    setDefaultBranch(null)
  }
  const [searchParams, setSearchParams] = useSearchParams()
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const repositoryNameInputChangeHandler = ({currentTarget}: ChangeEvent<HTMLInputElement>) => {
    const {value} = currentTarget

    setSelectedRepo(state => ({
      ...state,
      url: value,
      name: value,
    }))
    generatePipelineNameHandler(value)
    setIsAnyVcsProviderVerified(false)
    setDefaultBranch(null)
  }
  const selectVcsProviderSelectChangeHandler = (value: VcsProvider) => {
    if (value.type === VcsProviderType.NEW_CONNECTION) {
      setSearchParams({...searchParamsObject, mode: 'loginScreen'})

      setSelectedProvider({
        type: undefined,
      })
    } else {
      requestAnimationFrame(() => {
        setSelectedProvider(value)
      })
      setSelectedRepo(null)
      setDefaultBranch(null)
      setHasError(false)
      setIsAnyVcsProviderVerified(false)
      setVcsRootId(null)
      isProtocolManuallyChangedRef.current = false
    }
  }
  const vcsAnyRepositoryAuthenticationFormSubmitHandler = (
    isPrivate: boolean,
    username?: string,
    password?: string,
  ) => {
    setSelectedProvider(state => ({
      ...state,
      ...{
        username,
        password,
      },
    }))
    setSelectedRepo(state => ({
      ...state,
      isPrivate,
    }))
    setIsAnyVcsProviderVerified(true)
  }

  const formSubmitHandler = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()

    if (!isFormValid) {
      return
    }

    if (selectedRepo?.url != null) {
      const {url} = selectedRepo
      const isSshProtocol = vcsProtocolRepositoryAuthType === ProtocolVcsRepository.SSH
      const {username, password, connectionId} = selectedProvider
      const createPipelineVcsCredentials =
        isSshProtocol && isVcsProviderTypeAny
          ? {
              sshKey: {
                name: username ?? '',
                passphrase: password,
              },
            }
          : {
              username,
              password,
            }
      const vcsSettings = {
        repositoryUrl: url,
        isPrivate: !!selectedRepo.isPrivate,
        branch: defaultBranch ?? branchNameDefault,
        branchSpecification,
        connectionId,
        trackPullRequests,
        ...createPipelineVcsCredentials,
      }
      if (pipelineId) {
        updatePipeline({pipelineId, ...vcsSettings})
      } else {
        createPipeline({
          pipelineName,
          parentProjectId: projectId,
          ...vcsSettings,
        })
      }
    } else if (isVcsRootSelected) {
      if (pipelineId) {
        updatePipeline({pipelineId, isExternal: true, externalVcsRootId: vcsRootId})
      } else {
        createPipeline({
          pipelineName,
          isExternal: true,
          externalVcsRootId: vcsRootId,
          parentProjectId: projectId,
        })
      }
    }
  }
  const selectVcsRootHandler = (id: string | null, name?: string, vcs?: string) => {
    setVcsRootId(id)

    if (vcs) {
      setVcsName(vcs)
    }

    if (name) {
      const generatedName = generatePipelineName(name, pipelineNames)

      setPipelineName(generatedName)
    }
  }
  const vcsProviderVerifiedLabelButtonClickHandler = () => setIsAnyVcsProviderVerified(false)
  const clickCancelButtonHandler = () => history.back()

  useEffect(() => {
    if (!isNotAuthorized) {
      return
    }
    const updatedProvider = vcsProviders.find(
      vcsProvider => vcsProvider.connectionId === selectedProvider.connectionId,
    )
    if (updatedProvider?.username != null) {
      setSelectedProvider(updatedProvider)
    }
  }, [vcsProviders, selectedProvider, isNotAuthorized])

  useEffect(() => {
    if (selectedRepo?.defaultBranch != null) {
      setDefaultBranch(selectedRepo.defaultBranch)
    }
  }, [selectedRepo?.defaultBranch])

  useEffect(() => {
    setVcsRootId(null)
  }, [projectId])

  useEffect(() => {
    if (isShowVcsAnyRepositoryAuthenticationForm) {
      const guessedProtocol = getGuessedGitProtocol(selectedRepo?.url)

      if (guessedProtocol && !isProtocolManuallyChangedRef.current) {
        setVcsProtocolRepositoryAuthType(guessedProtocol)
      }
    }
  }, [isShowVcsAnyRepositoryAuthenticationForm, selectedRepo?.url])

  return {
    vcsRootId,
    vcsName,
    pipelineName,
    isRepoSelected,
    isFormValid,
    defaultBranch,
    branchSpecification,
    trackPullRequests,
    isNotAuthorized,
    hasError,
    selectedRepo,
    selectedProvider,
    isLoading: pipelineCreating || pipelineUpdating,
    onVcsLoginWithErrorReset,
    onError,
    isVcsProviderTypeAny,
    isExistingVcsRootProvider,
    isShowVcsAnyRepositoryAuthenticationForm,
    isShowLoginAlert,
    isAnyVcsProviderVerified,
    vcsHttpsRepositoryAuthType,
    vcsProtocolRepositoryAuthType,
    vcsProtocolRepositoryAuthenticationFormChangeHandler,
    vcsHttpsRepositoryAuthenticationFormChangeAuthTypeHandler,
    vcsProviderVerifiedLabelButtonClickHandler,
    vcsAnyRepositoryAuthenticationFormSubmitHandler,
    repositoryNameInputChangeHandler,
    repositoryNameSelectChangeHandler,
    selectVcsProviderSelectChangeHandler,
    setDefaultBranch,
    setPipelineName,
    setPipelineNameError,
    setBranchSpecification,
    setTrackPullRequests,
    formSubmitHandler,
    selectVcsRootHandler,
    clickCancelButtonHandler,
  }
}

export default usePipelineForm
